#!/usr/bin/env bash
# Build step 2 of 3 (its own cached layer): compile + install HylaFAX+ from
# source, install IAXmodem (Debian package). A failure here re-runs only this
# step on the next build; the PBX install layer comes from cache.
# Per-container modem/peer/dialplan config is generated by ipbx-entrypoint.
set -uo pipefail

# The Incredible PBX installer adds Webmin's retired "sarge" repository. Its
# signing key is gone, so every later `apt-get update` fails ("is not signed",
# exit 100). The current Webmin repo (download/newkey ... stable) is also
# configured, so commenting the old one out loses nothing. Done before the
# WITH_HYLAFAX check so later apt steps work either way.
for f in /etc/apt/sources.list /etc/apt/sources.list.d/*.list; do
  [[ -f $f ]] || continue
  if grep -qE '^[[:space:]]*deb[[:space:]].*download\.webmin\.com/download/repository[[:space:]]+sarge' "$f"; then
    sed -i -E 's@^([[:space:]]*deb[[:space:]].*download\.webmin\.com/download/repository[[:space:]]+sarge.*)$@# disabled at image build (retired Webmin repo, unsigned): \1@' "$f"
    echo "[hylafax] disabled retired Webmin 'sarge' repo in $f"
  fi
done

if [[ ${WITH_HYLAFAX:-1} != 1 ]]; then
  echo "[hylafax] WITH_HYLAFAX=${WITH_HYLAFAX:-}, skipping"
  exit 0
fi
: "${HYLAFAX_VERSION:?}" "${HYLAFAX_MD5:?}"
HYLAFAX_URL=${HYLAFAX_URL:-https://prdownloads.sourceforge.net/hylafax/hylafax-${HYLAFAX_VERSION}.tar.gz?download}
BUILD_DIR=$(cd "$(dirname "$0")" && pwd)
LOG=/var/log/hylafax-build.log
export DEBIAN_FRONTEND=noninteractive

say(){ echo "[hylafax $(date +%T)] $*"; }
die(){
  echo "BUILD FAILED (hylafax): $*"
  echo "----- last 120 lines of $LOG -----"
  tail -n 120 "$LOG" 2>/dev/null | sed 's/\x1b\[[0-9;?]*[A-Za-z]//g' | tr -cd '\11\12\40-\176'
  echo "----- end of log -----"
  exit 1
}
step(){  # step "label" cmd... : run, log, die with context on failure
  local label=$1; shift
  say "$label"
  echo "===== $label: $* =====" >>"$LOG"
  "$@" >>"$LOG" 2>&1 || die "$label failed (exit $?)"
}

say "=== HylaFAX+ ${HYLAFAX_VERSION} + IAXmodem ==="
step "apt-get update" apt-get update
step "install build deps + iaxmodem" apt-get install -y --no-install-recommends \
    build-essential libtiff-dev libjbig-dev libjpeg-dev zlib1g-dev libpam0g-dev libssl-dev \
    ghostscript libtiff-tools sharutils gawk psmisc file iaxmodem

# Debian's iaxmodem sysv service would run all modems as one unit; we use iaxmodem@.service
/usr/bin/systemctl mask iaxmodem.service >/dev/null 2>&1 || true
rm -f /etc/iaxmodem/ttyIAX* 2>/dev/null

SRC=/usr/src/hylafax
mkdir -p "$SRC" && cd "$SRC" || die "no $SRC"
step "download" wget -q -O "hylafax-${HYLAFAX_VERSION}.tar.gz" "$HYLAFAX_URL"
echo "${HYLAFAX_MD5}  hylafax-${HYLAFAX_VERSION}.tar.gz" | md5sum -c - || die "MD5 mismatch"
step "extract" tar xzf "hylafax-${HYLAFAX_VERSION}.tar.gz"
cd "hylafax-${HYLAFAX_VERSION}" || die "source dir missing"

step "configure" ./configure --nointeractive \
  --with-DIR_BIN=/usr/bin --with-DIR_SBIN=/usr/sbin --with-DIR_LIBEXEC=/usr/sbin \
  --with-DIR_LIB=/usr/lib --with-DIR_LIBDATA=/etc/hylafax --with-DIR_SPOOL=/var/spool/hylafax \
  --with-DIR_MAN=/usr/share/man --with-DIR_LOCKS=/var/lock \
  --with-PATH_GSRIP=/usr/bin/gs --with-TIFFBIN=/usr/bin --with-AFM=no --with-AWK=/usr/bin/gawk \
  --with-PATH_GETTY=/sbin/agetty --with-PATH_VGETTY=/bin/false --with-PATH_EGETTY=/bin/false \
  --with-SYSVINIT=no --with-PAGESIZE="North American Letter"
# Serial on purpose: HylaFAX+ makefiles are not parallel-safe (with -jN a
# program can be linked before libfaxutil.so exists). Takes a few minutes.
step "make" make
step "make install" make install

say "faxsetup"
faxsetup -server -nointeractive >>"$LOG" 2>&1 || say "faxsetup returned $? (checking result)"
[[ -f /var/spool/hylafax/etc/setup.cache ]] || die "faxsetup did not create setup.cache"
for b in faxq faxgetty sendfax hfaxd faxstat; do
  command -v "$b" >/dev/null || die "HylaFAX+ binary missing: $b"
done

# Modem config template (entrypoint stamps out config.ttyIAX<n> from it)
install -m 0644 "$BUILD_DIR/config.iaxmodem.template" /etc/hylafax/config.iaxmodem.template

# Housekeeping jobs
cat > /etc/cron.d/hylafax <<'EOF'
0 * * * *  root  /usr/sbin/faxqclean >/dev/null 2>&1
15 4 * * * root  /usr/sbin/faxcron -info 35 -log 35 -rcv 35 >/dev/null 2>&1
EOF

cd / && rm -rf "$SRC"
apt-get clean
say "=== HylaFAX+ ${HYLAFAX_VERSION} installed ==="
